-- GROWTH-PM-1 (Rowan 2026-11-12, charter pillar reach; autonomy): a growth product manager for every product. Rowan: "growth, product growth. That's what a
-- product manager is about ... We're not just fixing bugs here. We're growing and improving." and "Growth product manager: targets, experiments, knobs, growth
-- and repair changes filed."
-- What runs (fleet_tasks growth-pm, hourly at :05, SQL only on fleet-exec; one cheap agent request per product per day at most):
--   targets     product_growth_metrics: 2 to 4 growth metrics per product (jobs, companion-today, papers, brand, ultrastable) with a 7-day target, read from live
--               tables every hour into product_growth_readings (v_product_growth_now) and metric_registry. Every other registry product rolls up to one of them
--               (product_growth_parent); products_without_growth_metrics (target 0) counts any that does not.
--   experiments growth_experiments: the product manager asks for the hypothesis with the best expected lift per unit of effort for the product's weakest metric
--               (score = lift / effort x (1 + gap to target)), files the top ones as GROWTH-1 issues with a code-task line (the code loop builds, tests and merges
--               them), records the baseline and a decision_log prediction ("<metric> >= <value> within 168 h") when the change merges, and after 7 days marks it
--               won, kept_flat or rolling_back; a rollback is filed as GROWTH-ROLLBACK-1 through the same code path.
--   knobs       product_growth_knobs: ops_config values the workers read and clamp (qnfo-jobsearch auto-apply, qnfo-social touchpoints, product_plus_daily_cap).
--               One knob moves one step at a time, is measured after 7 days and is kept or restored automatically.
--   repair      a growth metric that fell to zero, halved, or whose counter went stale gets a GROWTH-REPAIR-1 issue through the same request and code path.
-- Priority: v_issue_queue_v2 multiplies the score of growth and feature issues by ops_config growth_priority_weight (default 3), and growth is high priority,
-- so the code loop (INTAKE_QUEUE_V2_SQL) takes growth before fixes of equal standing. growth_share_7d (target >= 0.5) and growth_experiment_win_rate_30d measure it.
-- Off switch: ops_config growth_pm = off stops new requests, filings and knob moves; measurement continues.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261112_growth_pm_queue_v2
-- Rollback: UPDATE fleet_tasks SET enabled = 0 WHERE id = 'growth-pm'; UPDATE fleet_crons SET enabled = 0 WHERE name = 'growth-pm-hourly'; UPDATE ops_config SET value = '1' WHERE key = 'growth_priority_weight'; UPDATE ops_config SET value = 'off' WHERE key = 'growth_pm'


-- Backup first: the view text of v_issue_queue_v2 before this file replaces it (the runner needs the backup ahead of any DROP).
CREATE TABLE IF NOT EXISTS bak_20261112_growth_pm_queue_v2 AS SELECT name, sql FROM sqlite_master WHERE name = 'v_issue_queue_v2';
CREATE TABLE IF NOT EXISTS product_growth_metrics (
  product TEXT NOT NULL, metric TEXT NOT NULL, label TEXT NOT NULL, lens TEXT NOT NULL, unit TEXT NOT NULL DEFAULT 'count', direction TEXT NOT NULL DEFAULT 'up',
  target_7d REAL NOT NULL, source TEXT NOT NULL DEFAULT 'sql', owner_loop TEXT NOT NULL DEFAULT 'growth-pm', active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), PRIMARY KEY (product, metric));
CREATE TABLE IF NOT EXISTS product_growth_parent (product TEXT PRIMARY KEY, parent TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS product_growth_counters (
  product TEXT NOT NULL, metric TEXT NOT NULL, value REAL, prev REAL, read_at TEXT, source TEXT, PRIMARY KEY (product, metric));
CREATE TABLE IF NOT EXISTS product_growth_readings (
  product TEXT NOT NULL, metric TEXT NOT NULL, hour TEXT NOT NULL, value REAL, prev REAL, target REAL, fresh INTEGER, PRIMARY KEY (product, metric, hour));
CREATE TABLE IF NOT EXISTS product_growth_knobs (
  knob TEXT PRIMARY KEY, product TEXT NOT NULL, metric TEXT NOT NULL, default_value REAL NOT NULL, min_value REAL NOT NULL, max_value REAL NOT NULL,
  step REAL NOT NULL, direction TEXT NOT NULL DEFAULT 'up', last_tried_at TEXT);
CREATE TABLE IF NOT EXISTS growth_experiments (
  id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, product TEXT NOT NULL, metric TEXT NOT NULL, request_instance TEXT UNIQUE,
  title TEXT, hypothesis TEXT, path TEXT, anchor_line TEXT, lift_pct REAL, effort INTEGER, score REAL,
  knob TEXT, from_value TEXT, to_value TEXT,
  status TEXT NOT NULL DEFAULT 'requested', issue_id INTEGER, task_id TEXT, pr_url TEXT,
  baseline REAL, predicted REAL, measured REAL, decision_id INTEGER, rollback_issue_id INTEGER,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), filed_at TEXT, shipped_at TEXT, due_at TEXT, decided_at TEXT, updated_at TEXT, note TEXT);
CREATE INDEX IF NOT EXISTS idx_growth_experiments_status ON growth_experiments (status, product);

