DROP VIEW IF EXISTS v_product_growth_now;
CREATE VIEW v_product_growth_now AS SELECT m.product, m.metric, m.label, m.lens, m.unit, m.target_7d AS target, m.source, CASE m.metric WHEN 'jobs_qualified_matches_7d' THEN (SELECT COUNT(*) FROM jobsearch_matches WHERE tier IN ('A','B') AND first_seen >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 days')) WHEN 'jobs_applications_7d' THEN (SELECT COUNT(*) FROM jobsearch_events WHERE event = 'applied' AND ts >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 days')) WHEN 'jobs_reply_rate_30d' THEN ROUND(1.0 * (SELECT COUNT(*) FROM jobsearch_events WHERE event IN ('replied','screening','interview','offer') AND ts >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-30 days')) / NULLIF((SELECT COUNT(*) FROM jobsearch_events WHERE event = 'applied' AND ts >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-30 days')), 0), 3) WHEN 'jobs_auto_apply_attempts_7d' THEN (SELECT COUNT(*) FROM jobsearch_auto WHERE ts >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 days')) WHEN 'research_papers_published_7d' THEN (SELECT COALESCE(SUM(papers_published), 0) FROM reader_yield_daily WHERE day >= date('now','-7 days')) WHEN 'research_engaged_external_7d' THEN (SELECT COALESCE(SUM(ga4_engaged_external), 0) FROM reader_yield_daily WHERE day >= date('now','-7 days')) WHEN 'research_external_pageviews_7d' THEN (SELECT COALESCE(SUM(ext_referred_pv), 0) FROM reader_yield_daily WHERE day >= date('now','-7 days')) WHEN 'brand_touch_outcomes_7d' THEN (SELECT COUNT(*) FROM touch_actions WHERE outcome IN ('followed-back','replied','liked-back') AND outcome_at >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 days')) WHEN 'brand_inbound_external_7d' THEN (SELECT COUNT(*) FROM v_email_inbound_external WHERE received_at >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 days')) WHEN 'brand_touch_actions_done_7d' THEN (SELECT COUNT(*) FROM touch_actions WHERE status = 'done' AND day >= date('now','-7 days')) WHEN 'ultrastable_merged_changes_7d' THEN (SELECT COUNT(*) FROM code_tasks WHERE status = 'merged' AND updated_at >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 days')) WHEN 'ultrastable_growth_shipped_7d' THEN (SELECT COUNT(*) FROM growth_experiments WHERE status IN ('shipped','won','kept_flat','rolling_back','rolled_back') AND kind = 'growth' AND shipped_at >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 days')) WHEN 'ultrastable_growth_win_rate_30d' THEN (SELECT ROUND(1.0 * SUM(status = 'won') / NULLIF(COUNT(*), 0), 3) FROM growth_experiments WHERE kind IN ('growth','knob') AND status IN ('won','kept_flat','rolling_back','rolled_back') AND decided_at >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-30 days')) ELSE (SELECT c.value FROM product_growth_counters c WHERE c.product = m.product AND c.metric = m.metric) END AS value, CASE m.metric WHEN 'jobs_qualified_matches_7d' THEN (SELECT COUNT(*) FROM jobsearch_matches WHERE tier IN ('A','B') AND first_seen >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-14 days') AND first_seen < strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 days')) WHEN 'jobs_applications_7d' THEN (SELECT COUNT(*) FROM jobsearch_events WHERE event = 'applied' AND ts >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-14 days') AND ts < strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 days')) WHEN 'jobs_reply_rate_30d' THEN ROUND(1.0 * (SELECT COUNT(*) FROM jobsearch_events WHERE event IN ('replied','screening','interview','offer') AND ts >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-60 days') AND ts < strftime('%Y-%m-%dT%H:%M:%SZ','now','-30 days')) / NULLIF((SELECT COUNT(*) FROM jobsearch_events WHERE event = 'applied' AND ts >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-60 days') AND ts < strftime('%Y-%m-%dT%H:%M:%SZ','now','-30 days')), 0), 3) WHEN 'jobs_auto_apply_attempts_7d' THEN (SELECT COUNT(*) FROM jobsearch_auto WHERE ts >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-14 days') AND ts < strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 days')) WHEN 'research_papers_published_7d' THEN (SELECT COALESCE(SUM(papers_published), 0) FROM reader_yield_daily WHERE day >= date('now','-14 days') AND day < date('now','-7 days')) WHEN 'research_engaged_external_7d' THEN (SELECT COALESCE(SUM(ga4_engaged_external), 0) FROM reader_yield_daily WHERE day >= date('now','-14 days') AND day < date('now','-7 days')) WHEN 'research_external_pageviews_7d' THEN (SELECT COALESCE(SUM(ext_referred_pv), 0) FROM reader_yield_daily WHERE day >= date('now','-14 days') AND day < date('now','-7 days')) WHEN 'brand_touch_outcomes_7d' THEN (SELECT COUNT(*) FROM touch_actions WHERE outcome IN ('followed-back','replied','liked-back') AND outcome_at >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-14 days') AND outcome_at < strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 days')) WHEN 'brand_inbound_external_7d' THEN (SELECT COUNT(*) FROM v_email_inbound_external WHERE received_at >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-14 days') AND received_at < strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 days')) WHEN 'brand_touch_actions_done_7d' THEN (SELECT COUNT(*) FROM touch_actions WHERE status = 'done' AND day >= date('now','-14 days') AND day < date('now','-7 days')) WHEN 'ultrastable_merged_changes_7d' THEN (SELECT COUNT(*) FROM code_tasks WHERE status = 'merged' AND updated_at >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-14 days') AND updated_at < strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 days')) WHEN 'ultrastable_growth_shipped_7d' THEN (SELECT COUNT(*) FROM growth_experiments WHERE status IN ('shipped','won','kept_flat','rolling_back','rolled_back') AND kind = 'growth' AND shipped_at >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-14 days') AND shipped_at < strftime('%Y-%m-%dT%H:%M:%SZ','now','-7 days')) WHEN 'ultrastable_growth_win_rate_30d' THEN (SELECT ROUND(1.0 * SUM(status = 'won') / NULLIF(COUNT(*), 0), 3) FROM growth_experiments WHERE kind IN ('growth','knob') AND status IN ('won','kept_flat','rolling_back','rolled_back') AND decided_at >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-60 days') AND decided_at < strftime('%Y-%m-%dT%H:%M:%SZ','now','-30 days')) ELSE (SELECT c.prev FROM product_growth_counters c WHERE c.product = m.product AND c.metric = m.metric) END AS prev, CASE WHEN m.source = 'counter' THEN COALESCE((SELECT c.read_at >= strftime('%Y-%m-%dT%H:%M:%SZ','now','-3 hours') FROM product_growth_counters c WHERE c.product = m.product AND c.metric = m.metric), 0) ELSE 1 END AS fresh FROM product_growth_metrics m WHERE m.active = 1;
DROP VIEW IF EXISTS v_product_growth_gap;
CREATE VIEW v_product_growth_gap AS SELECT g.*, CASE WHEN g.target > 0 AND g.value IS NOT NULL THEN MAX(0.0, 1.0 - g.value / g.target) ELSE 1.0 END AS gap, CASE WHEN g.prev IS NULL OR g.prev = 0 THEN NULL ELSE ROUND((g.value - g.prev) / g.prev, 3) END AS trend FROM v_product_growth_now g;
DROP VIEW IF EXISTS v_growth_products_uncovered;
CREATE VIEW v_growth_products_uncovered AS SELECT r.product FROM product_registry r WHERE r.state = 'active' AND (SELECT COUNT(*) FROM product_growth_metrics m WHERE m.product = r.product AND m.active = 1) < 2 AND NOT EXISTS (SELECT 1 FROM product_growth_parent pp JOIN product_growth_metrics m2 ON m2.product = pp.parent AND m2.active = 1 WHERE pp.product = r.product GROUP BY pp.parent HAVING COUNT(*) >= 2);


DROP VIEW IF EXISTS v_issue_queue_v2;
CREATE VIEW v_issue_queue_v2 AS
SELECT ROW_NUMBER() OVER (ORDER BY (q.prank = 0) DESC, q.aged DESC, q.score DESC, q.id) AS pos, q.*
FROM (
  SELECT f.*, ROUND(f.impact * f.probability * (f.capability_gain + f.reach_gain) * (1.0 / f.remediation_cost) * f.trust * (1 + f.direction) * f.growth_weight, 3) AS score
  FROM (
    SELECT a.id,
      CASE a.priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 WHEN 'low' THEN 3 ELSE 4 END AS prank,
      a.priority, a.title, a.category, a.source, t.owner, t.triage_state,
      CASE WHEN instr(COALESCE(a.description, ''), 'code-task:') > 0 THEN 1 ELSE 0 END AS has_code_task,
      CASE WHEN EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status = 'active') THEN 1 ELSE 0 END AS has_contract,
      a.linked_session, a.created_at, a.updated_at,
      CASE WHEN a.created_at < (CAST(strftime('%s', 'now') AS INTEGER) - 3600) * 1000 THEN 1 ELSE 0 END AS aged,
      COALESCE(s.impact, CASE a.priority WHEN 'critical' THEN 5 WHEN 'high' THEN 4 WHEN 'medium' THEN 3 WHEN 'low' THEN 2 ELSE 3 END) AS impact,
      COALESCE(s.probability, CASE (SELECT c.last_verdict FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN ('active', 'holding') ORDER BY c.last_attempt_at DESC LIMIT 1)
                                WHEN 'fail' THEN 5 WHEN 'pass' THEN 2 ELSE 3 END) AS probability,
      COALESCE(s.capability_gain, CASE WHEN lower(COALESCE(a.category, '')) IN ('autonomy', 'automation', 'core', 'pipeline', 'reliability', 'remediation', 'continuous-improvement', 'growth', 'feature') THEN 4 ELSE 2 END) AS capability_gain,
      COALESCE(s.reach_gain, CASE WHEN lower(COALESCE(a.category, '')) IN ('reach', 'research', 'quality', 'content-integrity', 'growth', 'feature') THEN 4 ELSE 1 END) AS reach_gain,
      COALESCE(s.remediation_cost, CASE WHEN instr(COALESCE(a.description, ''), 'code-task:') > 0 THEN 2 WHEN instr(COALESCE(a.description, ''), 'session-task:') > 0 THEN 4 ELSE 3 END) AS remediation_cost,
      CASE WHEN instr(COALESCE(a.description, ''), 'code-task:') > 0
           THEN COALESCE((SELECT l.trust_score FROM trust_ledger l WHERE l.surface = 'code-loop' AND l.action_class = 'merge'), 0.5) ELSE 0.5 END AS trust,
      COALESCE((SELECT d.confidence FROM inferred_direction d WHERE d.direction = 'category:' || COALESCE(a.category, 'uncategorised')
                  AND d.day >= date('now', '-7 days') ORDER BY d.day DESC LIMIT 1), 0) AS direction,
      CASE WHEN lower(COALESCE(a.category, '')) IN ('growth', 'feature') THEN COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = 'growth_priority_weight' AND CAST(o.value AS REAL) > 0), 3.0) ELSE 1.0 END AS growth_weight
    FROM agent_issues a LEFT JOIN issue_triage t ON t.issue_id = a.id LEFT JOIN issue_priority_scores s ON s.issue_id = a.id
    WHERE a.status = 'open'
  ) f
) q;

INSERT OR IGNORE INTO ops_config (key, value, note, updated_at) VALUES ('growth_pm', 'on', 'GROWTH-PM-1 master switch: off stops new requests, filings and knob moves; measurement continues', strftime('%Y-%m-%dT%H:%M:%SZ','now'));
INSERT OR IGNORE INTO ops_config (key, value, note, updated_at) VALUES ('growth_priority_weight', '3', 'GROWTH-PM-1: v_issue_queue_v2 multiplies the score of growth and feature issues by this', strftime('%Y-%m-%dT%H:%M:%SZ','now'));
INSERT OR IGNORE INTO ops_config (key, value, note, updated_at) VALUES ('growth_pm_max_in_flight', '4', 'GROWTH-PM-1: growth experiments filed or building at once', strftime('%Y-%m-%dT%H:%M:%SZ','now'));
INSERT OR IGNORE INTO ops_config (key, value, note, updated_at) VALUES ('growth_pm_daily_requests', '5', 'GROWTH-PM-1: hypothesis and repair agent requests a day, all products', strftime('%Y-%m-%dT%H:%M:%SZ','now'));
INSERT OR IGNORE INTO ops_config (key, value, note, updated_at) VALUES ('growth_pm_min_lift_pct', '5', 'GROWTH-PM-1: a kept experiment that grew less than this is kept_flat, not won', strftime('%Y-%m-%dT%H:%M:%SZ','now'));
INSERT OR IGNORE INTO ops_config (key, value, note, updated_at) VALUES ('growth_pm_rollback_drop_pct', '5', 'GROWTH-PM-1: an experiment whose metric fell more than this below its baseline is rolled back', strftime('%Y-%m-%dT%H:%M:%SZ','now'));
UPDATE ops_config SET value = value || ',growth-pm|GROWTH-1:,growth-pm|GROWTH-REPAIR-1:,growth-pm|GROWTH-ROLLBACK-1:', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE key = 'code_merge_trusted_sources' AND instr(value, 'growth-pm|GROWTH-1:') = 0;
INSERT OR IGNORE INTO management_personas (persona_key, level, scope, charter, kpis, decision_authority, sla_min, path_a, path_b, status, updated_at) VALUES ('product-manager:growth', 'function', 'growth', 'Grow every product: set growth targets from live data, find the weakest metric, run ranked experiments and knob moves, file growth and repair changes through the code loop, measure each against its logged prediction and keep or roll back.', 'growth_share_7d >= 0.5, growth_experiment_win_rate_30d, products_without_growth_metrics = 0', 'files GROWTH-1, GROWTH-REPAIR-1 and GROWTH-ROLLBACK-1 issues (code loop builds and merges), moves growth knobs one step within clamped ranges and restores them', 60, 'fleet_tasks growth-pm', 'fleet_tasks management-personas-plus (product plus)', 'active', strftime('%Y-%m-%dT%H:%M:%SZ','now'));

-- The workflow (fleet-exec runs each sql step in order; a step that fails names itself in fleet_runs).
INSERT OR REPLACE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at) VALUES ('growth-pm', 'GROWTH-PM-1: growth product manager (targets, ranked experiments, knobs, growth and repair changes)', 'workflow', '{"steps":[{"type":"sql","name":"gp-read","db":"AUDIT","sql":"INSERT OR REPLACE INTO product_growth_readings (product, metric, hour, value, prev, target, fresh) SELECT product, metric, strftime(''%Y-%m-%dT%H:00:00Z'',''now''), value, prev, target, fresh FROM v_product_growth_now"},{"type":"sql","name":"gp-registry","db":"AUDIT","sql":"INSERT OR IGNORE INTO metric_registry (metric, layer, kind, formula, source_of_truth, target, owner, disposition_actor, refresh_cadence, state) SELECT m.metric, ''growth'', ''target'', m.label, ''qnfo-audit.v_product_growth_now (GROWTH-PM-1)'', ''>= '' || m.target_7d, ''growth-pm'', ''agent:product-manager:growth'', ''hourly'', ''UNMEASURED'' FROM product_growth_metrics m WHERE m.active = 1"},{"type":"sql","name":"gp-metric-sync","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT g.value FROM v_product_growth_now g WHERE g.metric = metric_registry.metric AND g.fresh = 1) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric IN (SELECT g.metric FROM v_product_growth_now g WHERE g.fresh = 1 AND g.value IS NOT NULL)"},{"type":"sql","name":"gp-request","db":"AUDIT","sql":"INSERT INTO cf_agent_requests (requester, kind, prompt, instance, priority) SELECT ''product-manager:'' || pr.product, ''run'', ''You are the growth product manager of '' || pr.product || '' ('' || COALESCE(pr.host, '''') || ''): '' || COALESCE(pr.what_for, '''') || ''. Your job is growth, not bug fixing: more people reached, more conversions, more outcomes. Live growth metrics: '' || COALESCE((SELECT group_concat(g.metric || '' = '' || COALESCE(CAST(ROUND(g.value, 3) AS TEXT), ''unmeasured'') || '' (prior 7 days '' || COALESCE(CAST(ROUND(g.prev, 3) AS TEXT), ''n/a'') || '', target '' || g.target || '')'', ''; '') FROM v_product_growth_now g WHERE g.product = pr.product), ''none'') || ''. The weakest is '' || w.metric || '' ('' || w.label || ''). Experiments already run (do not repeat; build on a won one): '' || COALESCE((SELECT group_concat(substr(h.title, 1, 70) || '' ['' || h.status || '']'', ''; '') FROM (SELECT title, status FROM growth_experiments WHERE product = pr.product AND title IS NOT NULL ORDER BY id DESC LIMIT 6) h), ''none yet'') || ''. Read the code of '' || pg.worker || ''/worker.js and the live tables behind the metric, then propose the ONE change with the best expected growth of '' || w.metric || '' per unit of effort: a new source, a new feature, a removed conversion bottleneck, unused data put to work, or less friction in a flow. One worker file, reversible, no personal data read or quoted, never qnfo-fleet-control, qnfo-ops, qnfo-deploy-guard, qnfo-code-orchestrator or .github. Reply with ONLY these lines, each on its own line, no preface:'' || char(10) || ''TITLE: <under 80 characters>'' || char(10) || ''WHY: <who notices it and why the metric moves, under 80 words>'' || char(10) || ''LIFT: <expected percent change of the metric in 7 days, a whole number>'' || char(10) || ''EFFORT: <1 to 5, 1 is a few lines>'' || char(10) || ''code-task: repo=qnfo-workers path=<one worker.js>'' || char(10) || ''code-anchor: <verbatim text that occurs exactly once in that file, next to the edit>'' || char(10) || ''EDIT: <the exact change, under 120 words>'', ''growth-'' || pr.product || ''-'' || strftime(''%Y%m%d'',''now''), ''medium'' FROM product_registry pr JOIN (SELECT ''jobs'' AS product, ''qnfo-jobsearch'' AS worker UNION ALL SELECT ''companion-today'', ''personal-companion'' UNION ALL SELECT ''papers'', ''qnfo-gateway'' UNION ALL SELECT ''brand'', ''qnfo-social'' UNION ALL SELECT ''ultrastable'', ''qnfo-gateway'') pg ON pg.product = pr.product JOIN (SELECT g.product, g.metric, g.label, g.gap FROM v_product_growth_gap g WHERE g.fresh = 1 AND g.gap = (SELECT MAX(g2.gap) FROM v_product_growth_gap g2 WHERE g2.product = g.product AND g2.fresh = 1) GROUP BY g.product) w ON w.product = pr.product WHERE COALESCE((SELECT value FROM ops_config WHERE key = ''growth_pm''), ''on'') <> ''off'' AND NOT EXISTS (SELECT 1 FROM growth_experiments e WHERE e.product = pr.product AND e.kind = ''growth'' AND e.status IN (''requested'',''proposed'',''filed'',''building'')) AND NOT EXISTS (SELECT 1 FROM cf_agent_requests q WHERE q.instance = ''growth-'' || pr.product || ''-'' || strftime(''%Y%m%d'',''now'')) AND (SELECT COUNT(*) FROM cf_agent_requests q WHERE q.instance LIKE ''growth-%-'' || strftime(''%Y%m%d'',''now'') AND q.instance NOT LIKE ''growth-repair-%'') < COALESCE((SELECT CAST(value AS INTEGER) FROM ops_config WHERE key = ''growth_pm_daily_requests''), 5) ORDER BY w.gap DESC LIMIT 2"},{"type":"sql","name":"gp-request-log","db":"AUDIT","sql":"INSERT OR IGNORE INTO growth_experiments (kind, product, metric, request_instance, status, updated_at) SELECT ''growth'', substr(q.requester, 17), (SELECT g.metric FROM v_product_growth_gap g WHERE g.product = substr(q.requester, 17) AND g.fresh = 1 ORDER BY g.gap DESC LIMIT 1), q.instance, ''requested'', strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') FROM cf_agent_requests q WHERE q.instance LIKE ''growth-%'' AND q.instance NOT LIKE ''growth-repair-%'' AND q.requester LIKE ''product-manager:%'' AND q.created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-2 hours'')"},{"type":"sql","name":"gp-repair-request","db":"AUDIT","sql":"INSERT INTO cf_agent_requests (requester, kind, prompt, instance, priority) SELECT ''product-manager:'' || pr.product, ''run'', ''You are the growth product manager of '' || pr.product || ''. The growth metric '' || w.metric || '' ('' || w.label || '') looks broken: '' || w.why || ''. Live growth metrics: '' || COALESCE((SELECT group_concat(g.metric || '' = '' || COALESCE(CAST(ROUND(g.value, 3) AS TEXT), ''unmeasured'') || '' (prior 7 days '' || COALESCE(CAST(ROUND(g.prev, 3) AS TEXT), ''n/a'') || '', target '' || g.target || '')'', ''; '') FROM v_product_growth_now g WHERE g.product = pr.product), ''none'') || ''. Find why it stopped (a failing source, a broken query, a stuck step, a counter no longer written) by reading '' || pg.worker || ''/worker.js and the tables behind the metric, and propose the ONE smallest code repair that brings it back. One worker file, no personal data read or quoted, never qnfo-fleet-control, qnfo-ops, qnfo-deploy-guard, qnfo-code-orchestrator or .github. Reply with ONLY these lines, each on its own line, no preface:'' || char(10) || ''TITLE: <under 80 characters>'' || char(10) || ''WHY: <who notices it and why the metric moves, under 80 words>'' || char(10) || ''LIFT: <expected percent change of the metric in 7 days, a whole number>'' || char(10) || ''EFFORT: <1 to 5, 1 is a few lines>'' || char(10) || ''code-task: repo=qnfo-workers path=<one worker.js>'' || char(10) || ''code-anchor: <verbatim text that occurs exactly once in that file, next to the edit>'' || char(10) || ''EDIT: <the exact change, under 120 words>'', ''growth-repair-'' || pr.product || ''-'' || w.metric || ''-'' || strftime(''%Y%m%d'',''now''), ''high'' FROM (SELECT g.product, g.metric, g.label, CASE WHEN g.fresh = 0 THEN ''its counter has not been written for over 3 hours'' WHEN g.value = 0 AND g.prev > 0 THEN ''it fell to 0 from '' || g.prev || '' the week before'' ELSE ''it fell from '' || g.prev || '' to '' || g.value || '' in a week'' END AS why FROM v_product_growth_now g WHERE g.fresh = 0 OR (g.value = 0 AND g.prev > 0) OR (g.unit = ''count'' AND g.prev >= 4 AND g.value < g.prev * 0.5)) w JOIN product_registry pr ON pr.product = w.product JOIN (SELECT ''jobs'' AS product, ''qnfo-jobsearch'' AS worker UNION ALL SELECT ''companion-today'', ''personal-companion'' UNION ALL SELECT ''papers'', ''qnfo-gateway'' UNION ALL SELECT ''brand'', ''qnfo-social'' UNION ALL SELECT ''ultrastable'', ''qnfo-gateway'') pg ON pg.product = pr.product WHERE COALESCE((SELECT value FROM ops_config WHERE key = ''growth_pm''), ''on'') <> ''off'' AND NOT EXISTS (SELECT 1 FROM growth_experiments e WHERE e.product = w.product AND e.metric = w.metric AND e.kind = ''repair'' AND (e.status IN (''requested'',''proposed'',''filed'',''building'') OR e.created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-3 days''))) AND NOT EXISTS (SELECT 1 FROM cf_agent_requests q WHERE q.instance LIKE ''growth-repair-'' || pr.product || ''-%-'' || strftime(''%Y%m%d'',''now'')) AND (SELECT COUNT(*) FROM cf_agent_requests q WHERE q.instance LIKE ''growth-repair-%-'' || strftime(''%Y%m%d'',''now'')) < 2 LIMIT 1"},{"type":"sql","name":"gp-repair-log","db":"AUDIT","sql":"INSERT OR IGNORE INTO growth_experiments (kind, product, metric, request_instance, status, updated_at) SELECT ''repair'', substr(q.requester, 17), (SELECT m.metric FROM product_growth_metrics m WHERE instr(q.instance, ''-'' || m.metric || ''-'') > 0 LIMIT 1), q.instance, ''requested'', strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') FROM cf_agent_requests q WHERE q.instance LIKE ''growth-repair-%'' AND q.created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-2 hours'')"},{"type":"sql","name":"gp-parse","db":"AUDIT","sql":"UPDATE growth_experiments SET title = substr(x.title, 1, 120), hypothesis = substr(x.raw, 1, 1500), path = x.path, anchor_line = substr(x.anchor, 1, 300), lift_pct = MIN(MAX(COALESCE(x.lift, 5), 1), 200), effort = MIN(MAX(COALESCE(x.effort, 3), 1), 5), score = ROUND(MIN(MAX(COALESCE(x.lift, 5), 1), 200) / MIN(MAX(COALESCE(x.effort, 3), 1), 5) * (1 + COALESCE((SELECT g.gap FROM v_product_growth_gap g WHERE g.product = growth_experiments.product AND g.metric = growth_experiments.metric), 1)), 3), status = CASE WHEN x.path LIKE ''%/worker.js'' AND x.anchor IS NOT NULL AND length(x.anchor) > 8 AND x.title IS NOT NULL AND NOT EXISTS (SELECT 1 FROM json_each(''[\"qnfo-fleet-control\",\"qnfo-ops\",\"qnfo-deploy-guard\",\"qnfo-containers-pilot\",\"qnfo-autonomy-scorer\",\"qnfo-observability\",\"qnfo-code-orchestrator\",\"qnfo-code-agent\"]'') d WHERE x.path LIKE d.value || ''/%'') THEN ''proposed'' ELSE ''rejected'' END, note = CASE WHEN x.path LIKE ''%/worker.js'' AND x.anchor IS NOT NULL THEN note ELSE ''reply did not name one allowed worker.js and an anchor'' END, updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') FROM (SELECT r.instance, CASE WHEN instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''TITLE:'') > 0 THEN trim(substr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''TITLE:'') + 6), 1, instr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''TITLE:'') + 6) || char(10), char(10)) - 1), '' `*'') END AS title, CAST(CASE WHEN instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''LIFT:'') > 0 THEN trim(substr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''LIFT:'') + 5), 1, instr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''LIFT:'') + 5) || char(10), char(10)) - 1), '' `*'') END AS REAL) AS lift, CAST(CASE WHEN instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''EFFORT:'') > 0 THEN trim(substr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''EFFORT:'') + 7), 1, instr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''EFFORT:'') + 7) || char(10), char(10)) - 1), '' `*'') END AS INTEGER) AS effort, CASE WHEN instr(CASE WHEN instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') > 0 THEN trim(substr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') + 10), 1, instr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') + 10) || char(10), char(10)) - 1), '' `*'') END, ''path='') > 0 THEN trim(CASE WHEN instr(substr(CASE WHEN instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') > 0 THEN trim(substr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') + 10), 1, instr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') + 10) || char(10), char(10)) - 1), '' `*'') END, instr(CASE WHEN instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') > 0 THEN trim(substr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') + 10), 1, instr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') + 10) || char(10), char(10)) - 1), '' `*'') END, ''path='') + 5) || '' '', '' '') > 0 THEN substr(substr(CASE WHEN instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') > 0 THEN trim(substr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') + 10), 1, instr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') + 10) || char(10), char(10)) - 1), '' `*'') END, instr(CASE WHEN instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') > 0 THEN trim(substr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') + 10), 1, instr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') + 10) || char(10), char(10)) - 1), '' `*'') END, ''path='') + 5), 1, instr(substr(CASE WHEN instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') > 0 THEN trim(substr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') + 10), 1, instr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') + 10) || char(10), char(10)) - 1), '' `*'') END, instr(CASE WHEN instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') > 0 THEN trim(substr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') + 10), 1, instr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task:'') + 10) || char(10), char(10)) - 1), '' `*'') END, ''path='') + 5) || '' '', '' '') - 1) END, '' `*'') END AS path, CASE WHEN instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-anchor:'') > 0 THEN trim(substr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-anchor:'') + 12), 1, instr(substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-anchor:'') + 12) || char(10), char(10)) - 1), '' `*'') END AS anchor, replace(replace(r.result, ''**'', ''''), char(13), '''') AS raw FROM cf_agent_requests r WHERE r.instance LIKE ''growth-%'' AND r.status = ''done'' AND instr(r.result, ''TITLE:'') > 0) x WHERE x.instance = growth_experiments.request_instance AND growth_experiments.status = ''requested''"},{"type":"sql","name":"gp-request-failed","db":"AUDIT","sql":"UPDATE growth_experiments SET status = ''rejected'', note = ''agent request '' || (SELECT r.status FROM cf_agent_requests r WHERE r.instance = growth_experiments.request_instance) || '' without a usable reply'', updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') WHERE status = ''requested'' AND (EXISTS (SELECT 1 FROM cf_agent_requests r WHERE r.instance = growth_experiments.request_instance AND (r.status = ''failed'' OR (r.status = ''done'' AND instr(COALESCE(r.result, ''''), ''TITLE:'') = 0))) OR created_at < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-1 day''))"},{"type":"sql","name":"gp-file","db":"AUDIT","sql":"INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT CASE e.kind WHEN ''repair'' THEN ''GROWTH-REPAIR-1: '' ELSE ''GROWTH-1: '' END || e.product || '' #'' || e.id || '': '' || e.title, ''code-task: repo=qnfo-workers path='' || e.path || char(10) || ''code-anchor: '' || e.anchor_line || char(10) || char(10) || ''GROWTH-PM-1 '' || e.kind || '' experiment #'' || e.id || '' for '' || e.product || '', metric '' || e.metric || '' now '' || COALESCE(CAST(ROUND(g.value, 3) AS TEXT), ''unmeasured'') || '' (prior 7 days '' || COALESCE(CAST(ROUND(g.prev, 3) AS TEXT), ''n/a'') || '', target '' || g.target || ''). Expected lift '' || e.lift_pct || '' percent at effort '' || e.effort || '' (score '' || e.score || '', ranked against the other proposals). '' || char(10) || ''prediction: '' || e.metric || '' >= '' || ROUND(COALESCE(g.value, 0) * (1 + e.lift_pct / 100.0), 3) || '' within 168 h of the merge'' || char(10) || ''Closing condition: the change merges through the code loop. growth-pm then records the baseline, closes this issue with the pull request as evidence, scores the prediction after 7 days and keeps the change or files GROWTH-ROLLBACK-1.'' || char(10) || char(10) || substr(e.hypothesis, 1, 1200), ''growth-pm'', CASE e.kind WHEN ''repair'' THEN ''reliability'' ELSE ''growth'' END, ''high'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER) * 1000, CAST(strftime(''%s'',''now'') AS INTEGER) * 1000 FROM growth_experiments e LEFT JOIN v_product_growth_now g ON g.product = e.product AND g.metric = e.metric WHERE e.status = ''proposed'' AND COALESCE((SELECT value FROM ops_config WHERE key = ''growth_pm''), ''on'') <> ''off'' AND (e.kind = ''repair'' OR (SELECT COUNT(*) FROM growth_experiments x WHERE x.kind IN (''growth'',''repair'') AND x.status IN (''filed'',''building'')) < COALESCE((SELECT CAST(value AS INTEGER) FROM ops_config WHERE key = ''growth_pm_max_in_flight''), 4)) AND NOT EXISTS (SELECT 1 FROM agent_issues i WHERE i.title LIKE ''GROWTH-%: '' || e.product || '' #'' || e.id || '':%'') ORDER BY e.kind = ''repair'' DESC, e.score DESC LIMIT 2"},{"type":"sql","name":"gp-filed","db":"AUDIT","sql":"UPDATE growth_experiments SET status = ''filed'', filed_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), issue_id = (SELECT MIN(i.id) FROM agent_issues i WHERE i.source = ''growth-pm'' AND i.title LIKE ''GROWTH-%: '' || growth_experiments.product || '' #'' || growth_experiments.id || '':%'') WHERE status = ''proposed'' AND EXISTS (SELECT 1 FROM agent_issues i WHERE i.source = ''growth-pm'' AND i.title LIKE ''GROWTH-%: '' || growth_experiments.product || '' #'' || growth_experiments.id || '':%'')"},{"type":"sql","name":"gp-map","db":"AUDIT","sql":"INSERT OR IGNORE INTO issue_project_map (issue_id, project_code, program_code, kind, updated_at) SELECT e.issue_id, ''W.'' || r.program_code, r.program_code, ''feature'', datetime(''now'') FROM growth_experiments e JOIN product_registry r ON r.product = e.product WHERE e.issue_id IS NOT NULL AND EXISTS (SELECT 1 FROM projects p WHERE p.project_code = ''W.'' || r.program_code)"},{"type":"sql","name":"gp-track","db":"AUDIT","sql":"UPDATE growth_experiments SET task_id = (SELECT t.id FROM code_tasks t WHERE t.id = ''ct_im'' || growth_experiments.issue_id OR t.goal LIKE ''[issue #'' || growth_experiments.issue_id || '']%'' ORDER BY t.status = ''merged'' DESC, t.updated_at DESC LIMIT 1), status = CASE WHEN status = ''filed'' THEN ''building'' ELSE status END, updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') WHERE status IN (''filed'',''building'') AND (SELECT t.id FROM code_tasks t WHERE t.id = ''ct_im'' || growth_experiments.issue_id OR t.goal LIKE ''[issue #'' || growth_experiments.issue_id || '']%'' ORDER BY t.status = ''merged'' DESC, t.updated_at DESC LIMIT 1) IS NOT NULL"},{"type":"sql","name":"gp-ship","db":"AUDIT","sql":"UPDATE growth_experiments SET status = ''shipped'', shipped_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), due_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''+7 days''), updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), pr_url = (SELECT t.pr_url FROM code_tasks t WHERE t.id = growth_experiments.task_id), baseline = (SELECT g.value FROM v_product_growth_now g WHERE g.product = growth_experiments.product AND g.metric = growth_experiments.metric), predicted = ROUND(COALESCE((SELECT g.value FROM v_product_growth_now g WHERE g.product = growth_experiments.product AND g.metric = growth_experiments.metric), 0) * (1 + COALESCE(lift_pct, 5) / 100.0), 3) WHERE status IN (''filed'',''building'') AND kind IN (''growth'',''repair'') AND EXISTS (SELECT 1 FROM code_tasks t WHERE t.id = growth_experiments.task_id AND t.status = ''merged'')"},{"type":"sql","name":"gp-close-evidence","db":"AUDIT","sql":"INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT e.issue_id, ''shipped'', ''triaged'', ''growth-pm'', datetime(''now''), ''growth experiment #'' || e.id || '' merged: '' || COALESCE(e.pr_url, e.task_id) || '' (code task '' || e.task_id || '' merged); baseline '' || COALESCE(e.baseline, ''n/a'') || '', prediction '' || e.metric || '' >= '' || e.predicted || '' scored after 7 days by growth-pm'' FROM growth_experiments e JOIN agent_issues a ON a.id = e.issue_id WHERE e.status = ''shipped'' AND a.status = ''open'' ON CONFLICT(issue_id) DO UPDATE SET close_evidence = excluded.close_evidence"},{"type":"sql","name":"gp-close-contracts","db":"AUDIT","sql":"UPDATE remediation_contracts SET status = ''superseded'', last_verdict = ''superseded:growth-experiment-shipped'', last_attempt_at = datetime(''now'') WHERE issue_id IN (SELECT e.issue_id FROM growth_experiments e JOIN agent_issues a ON a.id = e.issue_id WHERE e.status = ''shipped'' AND a.status = ''open'') AND status IN (''active'',''holding'',''needs-machine-probe'',''probe-review-refused'')"},{"type":"sql","name":"gp-close","db":"AUDIT","sql":"UPDATE agent_issues SET status = ''closed'', close_channel = ''auto:growth-pm'', updated_at = CAST(strftime(''%s'',''now'') AS INTEGER) * 1000 WHERE status = ''open'' AND source = ''growth-pm'' AND id IN (SELECT e.issue_id FROM growth_experiments e WHERE e.status = ''shipped'')"},{"type":"sql","name":"gp-abandon","db":"AUDIT","sql":"UPDATE growth_experiments SET status = ''abandoned'', note = CASE WHEN EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = growth_experiments.issue_id AND a.status = ''closed'') THEN ''issue closed without a merged change'' ELSE ''no merged change within 5 days; the hypothesis returns to the pool'' END, updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') WHERE status IN (''filed'',''building'') AND (EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = growth_experiments.issue_id AND a.status = ''closed'') OR filed_at < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-5 days'')) AND NOT EXISTS (SELECT 1 FROM code_tasks t WHERE t.id = growth_experiments.task_id AND t.status = ''merged'')"},{"type":"sql","name":"gp-abandon-evidence","db":"AUDIT","sql":"INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT e.issue_id, ''abandoned'', ''triaged'', ''growth-pm'', datetime(''now''), ''growth experiment #'' || e.id || '' abandoned: '' || e.note FROM growth_experiments e JOIN agent_issues a ON a.id = e.issue_id WHERE e.status = ''abandoned'' AND a.status = ''open'' ON CONFLICT(issue_id) DO UPDATE SET close_evidence = excluded.close_evidence"},{"type":"sql","name":"gp-abandon-close","db":"AUDIT","sql":"UPDATE agent_issues SET status = ''closed'', close_channel = ''auto:growth-pm'', updated_at = CAST(strftime(''%s'',''now'') AS INTEGER) * 1000 WHERE status = ''open'' AND source = ''growth-pm'' AND id IN (SELECT e.issue_id FROM growth_experiments e WHERE e.status = ''abandoned'')"},{"type":"sql","name":"gp-knob-try","db":"AUDIT","sql":"INSERT INTO growth_experiments (kind, product, metric, request_instance, title, knob, from_value, to_value, lift_pct, effort, score, status, shipped_at, due_at, baseline, predicted, updated_at) SELECT ''knob'', k.product, k.metric, ''knob-'' || k.knob || ''-'' || strftime(''%Y%m%d'',''now''), ''Move '' || k.knob || '' '' || k.direction || '' from '' || CASE WHEN (COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value)) = CAST((COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value)) AS INTEGER) THEN CAST(CAST((COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value)) AS INTEGER) AS TEXT) ELSE CAST((COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value)) AS TEXT) END || '' to '' || CASE WHEN (CASE k.direction WHEN ''down'' THEN MAX(k.min_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) - k.step) ELSE MIN(k.max_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) + k.step) END) = CAST((CASE k.direction WHEN ''down'' THEN MAX(k.min_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) - k.step) ELSE MIN(k.max_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) + k.step) END) AS INTEGER) THEN CAST(CAST((CASE k.direction WHEN ''down'' THEN MAX(k.min_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) - k.step) ELSE MIN(k.max_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) + k.step) END) AS INTEGER) AS TEXT) ELSE CAST((CASE k.direction WHEN ''down'' THEN MAX(k.min_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) - k.step) ELSE MIN(k.max_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) + k.step) END) AS TEXT) END, k.knob, CASE WHEN (COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value)) = CAST((COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value)) AS INTEGER) THEN CAST(CAST((COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value)) AS INTEGER) AS TEXT) ELSE CAST((COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value)) AS TEXT) END, CASE WHEN (CASE k.direction WHEN ''down'' THEN MAX(k.min_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) - k.step) ELSE MIN(k.max_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) + k.step) END) = CAST((CASE k.direction WHEN ''down'' THEN MAX(k.min_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) - k.step) ELSE MIN(k.max_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) + k.step) END) AS INTEGER) THEN CAST(CAST((CASE k.direction WHEN ''down'' THEN MAX(k.min_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) - k.step) ELSE MIN(k.max_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) + k.step) END) AS INTEGER) AS TEXT) ELSE CAST((CASE k.direction WHEN ''down'' THEN MAX(k.min_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) - k.step) ELSE MIN(k.max_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) + k.step) END) AS TEXT) END, 5, 1, 5, ''shipped'', strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''+7 days''), g.value, ROUND(COALESCE(g.value, 0) * 1.05, 3), strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') FROM product_growth_knobs k JOIN v_product_growth_now g ON g.product = k.product AND g.metric = k.metric WHERE COALESCE((SELECT value FROM ops_config WHERE key = ''growth_pm''), ''on'') <> ''off'' AND g.fresh = 1 AND g.value IS NOT NULL AND CASE k.direction WHEN ''down'' THEN MAX(k.min_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) - k.step) ELSE MIN(k.max_value, COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) + k.step) END <> COALESCE((SELECT CAST(o.value AS REAL) FROM ops_config o WHERE o.key = k.knob), k.default_value) AND NOT EXISTS (SELECT 1 FROM growth_experiments e WHERE e.kind = ''knob'' AND e.product = k.product AND e.status IN (''shipped'',''rolling_back'')) AND (k.last_tried_at IS NULL OR k.last_tried_at < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-7 days'')) AND NOT EXISTS (SELECT 1 FROM growth_experiments e WHERE e.request_instance = ''knob-'' || k.knob || ''-'' || strftime(''%Y%m%d'',''now'')) ORDER BY k.last_tried_at IS NOT NULL, k.last_tried_at LIMIT 1"},{"type":"sql","name":"gp-knob-apply","db":"AUDIT","sql":"INSERT INTO ops_config (key, value, note, updated_at) SELECT e.knob, e.to_value, ''GROWTH-KNOBS-1: growth experiment #'' || e.id || '' (was '' || e.from_value || ''); growth-pm restores it if '' || e.metric || '' falls'', strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') FROM growth_experiments e WHERE e.kind = ''knob'' AND e.status = ''shipped'' AND e.shipped_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-2 hours'') AND e.note IS NULL ON CONFLICT(key) DO UPDATE SET value = excluded.value, note = excluded.note, updated_at = excluded.updated_at"},{"type":"sql","name":"gp-knob-mark","db":"AUDIT","sql":"UPDATE growth_experiments SET note = ''applied '' || strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') WHERE kind = ''knob'' AND status = ''shipped'' AND note IS NULL AND EXISTS (SELECT 1 FROM ops_config o WHERE o.key = growth_experiments.knob AND o.value = growth_experiments.to_value)"},{"type":"sql","name":"gp-knob-tried","db":"AUDIT","sql":"UPDATE product_growth_knobs SET last_tried_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') WHERE knob IN (SELECT e.knob FROM growth_experiments e WHERE e.kind = ''knob'' AND e.shipped_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-2 hours''))"},{"type":"sql","name":"gp-decision","db":"AUDIT","sql":"INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain) SELECT ''growth-pm'', ''the '' || e.kind || '' change moves '' || e.metric || '' up within 7 days'', COALESCE(e.title, e.knob), ''growth-experiment #'' || e.id || '' '' || COALESCE(e.pr_url, e.knob || '' '' || e.from_value || '' -> '' || e.to_value), ''shipped'', ''product '' || e.product || '' only'', CASE e.kind WHEN ''knob'' THEN ''ops_config '' || e.knob || '' back to '' || e.from_value || '' (growth-pm does it)'' ELSE ''GROWTH-ROLLBACK-1 through the code loop (growth-pm files it)'' END, ''growth'', e.metric || '' >= '' || e.predicted || '' within 168 h'', e.metric FROM growth_experiments e WHERE e.status = ''shipped'' AND e.decision_id IS NULL AND e.predicted IS NOT NULL AND NOT EXISTS (SELECT 1 FROM decision_log d WHERE d.actor = ''growth-pm'' AND d.evidence LIKE ''growth-experiment #'' || e.id || '' %'')"},{"type":"sql","name":"gp-decision-link","db":"AUDIT","sql":"UPDATE growth_experiments SET decision_id = (SELECT MAX(d.id) FROM decision_log d WHERE d.actor = ''growth-pm'' AND d.evidence LIKE ''growth-experiment #'' || growth_experiments.id || '' %'') WHERE decision_id IS NULL AND status = ''shipped''"},{"type":"sql","name":"gp-prediction","db":"AUDIT","sql":"INSERT OR IGNORE INTO decision_predictions (decision_id, kind, subject, op, value, due_at, origin) SELECT e.decision_id, ''metric'', e.metric, ''>='', e.predicted, e.due_at, ''seeded'' FROM growth_experiments e WHERE e.decision_id IS NOT NULL AND e.status = ''shipped'' AND e.predicted IS NOT NULL"},{"type":"sql","name":"gp-measure","db":"AUDIT","sql":"UPDATE growth_experiments SET measured = (SELECT g.value FROM v_product_growth_now g WHERE g.product = growth_experiments.product AND g.metric = growth_experiments.metric AND g.fresh = 1), decided_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), status = CASE WHEN (SELECT g.value FROM v_product_growth_now g WHERE g.product = growth_experiments.product AND g.metric = growth_experiments.metric AND g.fresh = 1) >= predicted AND (SELECT g.value FROM v_product_growth_now g WHERE g.product = growth_experiments.product AND g.metric = growth_experiments.metric AND g.fresh = 1) >= COALESCE(baseline, 0) * (1 + COALESCE((SELECT CAST(value AS REAL) FROM ops_config WHERE key = ''growth_pm_min_lift_pct''), 5) / 100.0) AND (SELECT g.value FROM v_product_growth_now g WHERE g.product = growth_experiments.product AND g.metric = growth_experiments.metric AND g.fresh = 1) > COALESCE(baseline, 0) THEN ''won'' WHEN COALESCE(baseline, 0) > 0 AND (SELECT g.value FROM v_product_growth_now g WHERE g.product = growth_experiments.product AND g.metric = growth_experiments.metric AND g.fresh = 1) < baseline * (1 - COALESCE((SELECT CAST(value AS REAL) FROM ops_config WHERE key = ''growth_pm_rollback_drop_pct''), 5) / 100.0) THEN ''rolling_back'' ELSE ''kept_flat'' END WHERE status = ''shipped'' AND due_at <= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') AND (SELECT g.value FROM v_product_growth_now g WHERE g.product = growth_experiments.product AND g.metric = growth_experiments.metric AND g.fresh = 1) IS NOT NULL"},{"type":"sql","name":"gp-knob-rollback","db":"AUDIT","sql":"UPDATE ops_config SET value = (SELECT e.from_value FROM growth_experiments e WHERE e.kind = ''knob'' AND e.status = ''rolling_back'' AND e.knob = ops_config.key ORDER BY e.id DESC LIMIT 1), note = ''GROWTH-KNOBS-1: restored by growth-pm after the metric fell'', updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') WHERE key IN (SELECT e.knob FROM growth_experiments e WHERE e.kind = ''knob'' AND e.status = ''rolling_back'')"},{"type":"sql","name":"gp-knob-flip","db":"AUDIT","sql":"UPDATE product_growth_knobs SET direction = CASE direction WHEN ''up'' THEN ''down'' ELSE ''up'' END WHERE knob IN (SELECT e.knob FROM growth_experiments e WHERE e.kind = ''knob'' AND e.status = ''rolling_back'')"},{"type":"sql","name":"gp-knob-rolled","db":"AUDIT","sql":"UPDATE growth_experiments SET status = ''rolled_back'', note = COALESCE(note, '''') || '' restored '' || strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') WHERE kind = ''knob'' AND status = ''rolling_back'' AND EXISTS (SELECT 1 FROM ops_config o WHERE o.key = growth_experiments.knob AND o.value = growth_experiments.from_value)"},{"type":"sql","name":"gp-rollback-file","db":"AUDIT","sql":"INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''GROWTH-ROLLBACK-1: '' || e.product || '' #'' || e.id || '': revert '' || substr(e.title, 1, 80), ''code-task: repo=qnfo-workers path='' || e.path || char(10) || ''code-anchor: '' || e.anchor_line || char(10) || char(10) || ''GROWTH-PM-1 rollback of experiment #'' || e.id || '' ('' || e.product || ''): revert only the change of '' || COALESCE(e.pr_url, e.task_id) || '', with no unrelated edits. Seven days after the merge '' || e.metric || '' read '' || e.measured || '' against a baseline of '' || e.baseline || '' (predicted '' || e.predicted || '').'' || char(10) || ''Closing condition: the revert merges; growth-pm marks the experiment rolled_back and closes this issue.'', ''growth-pm'', ''growth'', ''high'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER) * 1000, CAST(strftime(''%s'',''now'') AS INTEGER) * 1000 FROM growth_experiments e WHERE e.kind IN (''growth'',''repair'') AND e.status = ''rolling_back'' AND e.rollback_issue_id IS NULL AND e.path IS NOT NULL AND NOT EXISTS (SELECT 1 FROM agent_issues i WHERE i.title LIKE ''GROWTH-ROLLBACK-1: '' || e.product || '' #'' || e.id || '':%'')"},{"type":"sql","name":"gp-rollback-link","db":"AUDIT","sql":"UPDATE growth_experiments SET rollback_issue_id = (SELECT MIN(i.id) FROM agent_issues i WHERE i.title LIKE ''GROWTH-ROLLBACK-1: '' || growth_experiments.product || '' #'' || growth_experiments.id || '':%'') WHERE status = ''rolling_back'' AND rollback_issue_id IS NULL"},{"type":"sql","name":"gp-rollback-done","db":"AUDIT","sql":"UPDATE growth_experiments SET status = ''rolled_back'', note = ''reverted by '' || COALESCE((SELECT t.pr_url FROM code_tasks t WHERE t.id = (SELECT t.id FROM code_tasks t WHERE t.id = ''ct_im'' || growth_experiments.rollback_issue_id OR t.goal LIKE ''[issue #'' || growth_experiments.rollback_issue_id || '']%'' ORDER BY t.status = ''merged'' DESC, t.updated_at DESC LIMIT 1)), ''the code loop''), updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') WHERE status = ''rolling_back'' AND kind IN (''growth'',''repair'') AND EXISTS (SELECT 1 FROM code_tasks t WHERE t.id = (SELECT t.id FROM code_tasks t WHERE t.id = ''ct_im'' || growth_experiments.rollback_issue_id OR t.goal LIKE ''[issue #'' || growth_experiments.rollback_issue_id || '']%'' ORDER BY t.status = ''merged'' DESC, t.updated_at DESC LIMIT 1) AND t.status = ''merged'')"},{"type":"sql","name":"gp-rollback-evidence","db":"AUDIT","sql":"INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT e.rollback_issue_id, ''reverted'', ''triaged'', ''growth-pm'', datetime(''now''), ''growth experiment #'' || e.id || '' '' || e.note FROM growth_experiments e JOIN agent_issues a ON a.id = e.rollback_issue_id WHERE e.status = ''rolled_back'' AND a.status = ''open'' ON CONFLICT(issue_id) DO UPDATE SET close_evidence = excluded.close_evidence"},{"type":"sql","name":"gp-rollback-close","db":"AUDIT","sql":"UPDATE agent_issues SET status = ''closed'', close_channel = ''auto:growth-pm'', updated_at = CAST(strftime(''%s'',''now'') AS INTEGER) * 1000 WHERE status = ''open'' AND source = ''growth-pm'' AND id IN (SELECT e.rollback_issue_id FROM growth_experiments e WHERE e.status = ''rolled_back'')"},{"type":"sql","name":"gp-m-growth-share","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT ROUND(1.0 * SUM(lower(COALESCE(a.category, '''')) IN (''growth'',''feature'')) / NULLIF(COUNT(*), 0), 3) FROM (SELECT CASE WHEN t.id LIKE ''ct_im%'' THEN CAST(substr(t.id, 6) AS INTEGER) WHEN t.goal LIKE ''[issue #%'' THEN CAST(substr(t.goal, 9, instr(t.goal, '']'') - 9) AS INTEGER) END AS iid FROM code_tasks t WHERE t.status = ''merged'' AND t.updated_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-7 days'')) x LEFT JOIN agent_issues a ON a.id = x.iid) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric = ''growth_share_7d''"},{"type":"sql","name":"gp-m-queue-share","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT ROUND(1.0 * SUM(lower(COALESCE(category, '''')) IN (''growth'',''feature'')) / NULLIF(COUNT(*), 0), 3) FROM v_issue_queue_v2 WHERE pos <= 20) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric = ''growth_queue_share_top20''"},{"type":"sql","name":"gp-m-win-rate","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT COALESCE((SELECT ROUND(1.0 * SUM(status = ''won'') / NULLIF(COUNT(*), 0), 3) FROM growth_experiments WHERE kind IN (''growth'',''knob'') AND status IN (''won'',''kept_flat'',''rolling_back'',''rolled_back'') AND decided_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-30 days'')), 0)) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric = ''growth_experiment_win_rate_30d''"},{"type":"sql","name":"gp-m-uncovered","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM v_growth_products_uncovered) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric = ''products_without_growth_metrics''"},{"type":"sql","name":"gp-m-heartbeat","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT CAST((julianday(''now'') - julianday(MAX(hour))) * 1440 AS INTEGER) FROM product_growth_readings) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric = ''growth_pm_heartbeat_age_min''"},{"type":"sql","name":"gp-brief","db":"AUDIT","sql":"INSERT OR REPLACE INTO persona_briefs (tick, persona_key, level, scope, verdict, decision, summary) SELECT strftime(''%Y-%m-%dT%H:00:00Z'',''now''), ''product-manager:growth'', ''function'', ''growth'', CASE WHEN (SELECT COUNT(*) FROM v_product_growth_gap WHERE gap > 0.5) > 3 THEN ''behind'' ELSE ''on-track'' END, ''ranked experiments, knob moves and repairs through the code loop'', (SELECT COUNT(*) FROM growth_experiments WHERE status IN (''filed'',''building'')) || '' building, '' || (SELECT COUNT(*) FROM growth_experiments WHERE status = ''shipped'') || '' measuring, '' || (SELECT COUNT(*) FROM growth_experiments WHERE status = ''won'') || '' won, '' || (SELECT COUNT(*) FROM growth_experiments WHERE status IN (''rolled_back'',''rolling_back'')) || '' rolled back. Weakest: '' || COALESCE((SELECT group_concat(product || '' '' || metric, '', '') FROM (SELECT product, metric FROM v_product_growth_gap ORDER BY gap DESC LIMIT 3)), ''none'') || ''.''"},{"type":"sql","name":"gp-actions","db":"AUDIT","sql":"INSERT INTO persona_actions (persona_key, kind, from_value, to_value, evidence) SELECT ''product-manager:growth'', ''growth-'' || e.kind || ''-'' || e.status, COALESCE(e.request_instance, CAST(e.id AS TEXT)), e.status, ''growth experiment #'' || e.id || '' '' || e.product || '' '' || e.metric || COALESCE('' issue '' || e.issue_id, '''') || COALESCE('' '' || e.pr_url, '''') FROM growth_experiments e WHERE e.updated_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-2 hours'') AND NOT EXISTS (SELECT 1 FROM persona_actions a WHERE a.persona_key = ''product-manager:growth'' AND a.from_value = COALESCE(e.request_instance, CAST(e.id AS TEXT)) AND a.to_value = e.status)"}]}', 120000, 1, 1, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'));
INSERT OR REPLACE INTO fleet_crons (name, cron_expr, task_id, enabled, timezone, updated_at) VALUES ('growth-pm-hourly', '5 * * * *', 'growth-pm', 1, 'UTC', strftime('%Y-%m-%dT%H:%M:%SZ','now'));

